Core Services Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(core_services_container, "Core Services Container") {
    Component(Telehealth_API_Controller, "Telehealth API Controller", "Spring Boot / Java", "Handles incoming routing requests from the API Gateway via gRPC over mTLS.")
    Component(Consent_Policy_Evaluator, "Consent Policy Evaluator", "Spring Boot / Java", "Evaluates cached consent policies by interacting with Memorystore for Redis.")
    Component(Audit_Logger, "Audit Logger", "Spring Boot / Java", "Stores immutable audit logs in Cloud Storage via HTTPS / GCP API.")
}

Rel(Telehealth_API_Controller, Consent_Policy_Evaluator, "Evaluates cached consent policies", "Redis Protocol over TLS")
Rel(Telehealth_API_Controller, Audit_Logger, "Dispatches compliance and audit records", "HTTPS / GCP API")

@enduml

Video Media Server.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Video_Media_Server, "Video Media Server") {
    Component(SFU_Core, "SFU Core", "Go / LiveKit Engine", "Handles real-time media streams and core SFU functionality.")
    Component(Room___Session_Manager, "Room & Session Manager", "Go", "Manages video rooms and user sessions.")
    Component(Adaptive_Bitrate_Controller, "Adaptive Bitrate Controller", "Go", "Dynamically adjusts media codecs and enforces audio-only fallback.")
    Component(Token_Verifier, "Token Verifier", "Go", "Validates incoming client JWTs locally.")
}

Rel(Room___Session_Manager, Core_Services_Container, "Validates session authorization", "gRPC over mTLS")
Rel(SFU_Core, Token_Verifier, "Validates incoming client JWTs locally", "In-Memory")
Rel(Adaptive_Bitrate_Controller, SFU_Core, "Dynamically adjusts media codecs and enforces audio-only fallback", "In-Memory Go API")

@enduml

Cloud SQL (PostgreSQL).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Cloud SQL (PostgreSQL) container

Container(Core Services Container, "Core Services Container", "Spring Boot / Java", "Core application services")

Container_Boundary("Cloud SQL (PostgreSQL)", "Cloud SQL (PostgreSQL)") {
    Component(ConnectionPoolingComponent, "Connection Pooling Component", "TCP/SSL", "Manages database sessions and connection pooling via TCP/SSL for core services.")
    Component(DatabaseInstanceComponent, "Database Instance Component", "PostgreSQL with pgaudit", "Manages physically isolated relational data instances in europe-west3 and us-central1 ensuring GDPR and HIPAA compliance.")
}

Rel(Core Services Container, ConnectionPoolingComponent, "Manages database sessions via TCP/SSL", "TCP/SSL")
Rel(ConnectionPoolingComponent, DatabaseInstanceComponent, "Routes queries to relational data instances", "PostgreSQL Wire Protocol")

@enduml

Cloud Pub/Sub.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Cloud Pub/Sub container

Container_Boundary("Cloud Pub/Sub", "Cloud Pub/Sub") {
    Component("Event Publisher", "Event Publisher", "Google Cloud Pub/Sub Publisher API / TLS 1.3", "Publishes asynchronous healthcare events and messages from Core Services and Integration Service.")
    Component("Event Consumer", "Event Consumer", "Google Cloud Pub/Sub Subscriber API / TLS 1.3", "Consumes asynchronous events to ensure resilient and prioritized delivery for critical healthcare workflows.")
}

Rel("Event Publisher", "Event Consumer", "Dispatches and routes asynchronous healthcare events via Google Cloud Pub/Sub using TLS 1.3.", "Google Cloud Pub/Sub / TLS 1.3")

@enduml
